INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M1-2-u5-C6','math',1,2,'u5',7,'규칙을 여러 가지 방법으로 나타내기 — 모양·수·몸',ARRAY['2수03-02']::text[],41) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X01','math',1,'u5',ARRAY['M1-2-u5-C1','M1-2-u5-C4','M1-2-u5-C6']::text[],'되풀이되는 부분을 처음이 아닌 중간부터 잡는다 — 「1, 1, 6」을 「1, 6, 1」로','되풀이되는 부분에 ○를 처음부터 묶게 하고 「처음 것부터」 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X02','math',1,'u5',ARRAY['M1-2-u5-C1','M1-2-u5-C2']::text[],'되풀이되는 부분의 길이를 잘못 잡는다 — 큰·작·작 을 큰·작 으로','묶음 표시를 한 뒤 묶음 안의 개수를 세어 확인하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X03','math',1,'u5',ARRAY['M1-2-u5-C1']::text[],'무엇이 반복되는지 똑똑히 말하지 못한다 — 「의자가 여러 개 있어요」처럼 색·크기·모양을 짚지 않음','「무엇이(색·크기·모양) 어떻게 반복되나」 문장 틀로 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X04','math',1,'u5',ARRAY['M1-2-u5-C2','M1-2-u5-C6']::text[],'물건·색만 다르면 다른 규칙이라고 본다 — 풀·풀·가위 와 검정·검정·흰색이 다른 규칙','두 줄을 나란히 놓고 되풀이되는 부분의 길이·차례가 같은지 짝 지어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X05','math',1,'u5',ARRAY['M1-2-u5-C2','M1-2-u5-C3']::text[],'규칙이 없는 배열도 규칙이 있다고 본다 — 마음대로 놓아도 무늬','되풀이되는 부분에 ○를 해 보게 하고 묶음이 안 되면 규칙이 아님을 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X06','math',1,'u5',ARRAY['M1-2-u5-C4','M1-2-u5-C5']::text[],'몇씩 커지는지 보지 않고 늘 1씩 커진다고 본다 — 1, 3, 5 다음을 6','옆의 수와 차이를 뛰어 세기로 재어 「몇씩」을 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X07','math',1,'u5',ARRAY['M1-2-u5-C4']::text[],'작아지는 규칙을 커지는 것으로 읽는다 — 28, 26, 24 다음을 26','화살표로 방향을 표시하고 「몇부터 시작하여 몇씩 작아져요」 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X08','math',1,'u5',ARRAY['M1-2-u5-C5']::text[],'수 배열표에서 아래로 갈 때도 1씩 커진다고 본다 — 세로줄 10씩을 1씩','세로 한 줄을 손가락으로 짚으며 12→22→32 를 읽고 차이 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X09','math',1,'u5',ARRAY['M1-2-u5-C5']::text[],'비스듬한 줄·색칠한 수의 규칙을 못 잡는다 — 11씩·9씩·3씩을 10씩이나 1씩으로','색칠한 수만 따로 적어 옆 수와 차이를 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X10','math',1,'u5',ARRAY['M1-2-u5-C6']::text[],'수로 나타낼 때 짝짓기만 하고 되풀이를 살리지 않는다 — 🚲=2, 🛺=3 이라고만 하고 끝','같은 규칙을 그림·수·몸짓 세 줄로 나란히 쓰고 묶음이 같은지 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M1-2-u5-X11','math',1,'u5',ARRAY['M1-2-u5-C2','M1-2-u5-C3']::text[],'되풀이 규칙으로 놓은 전체에서 한 물건의 개수를 한 덩이 안의 개수로 답한다 — 6개 중 지우개를 1개','덩이를 세어 「덩이 수 × 덩이 안 개수」로 다시 세어 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#1','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'mc','auto','안전 고깔이 줄지어 있어요. 빈칸에 올 고깔은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],true,'{"seq":1,"concept":"M1-2-u5-C1","difficulty":1,"kind":"mc","stem":"안전 고깔이 줄지어 있어요. 빈칸에 올 고깔은 무엇인가요?","asset":{"type":"pattern_row","items":["🔶","🔺","🔶","🔺","🔶","🔺",null]},"options":[{"t":"🔶","correct":true},{"t":"🔺","mis":"M1-2-u5-X01"},{"t":"🟦","mis":"M1-2-u5-X03"}],"variant_rule":{"repeat":{"ask":"next","unit":[2,2],"pool":["🔶","🔺","🟦","⭐","🟢","🍎"]}},"explanation":["🔶, 🔺 가 되풀이돼요.","🔺 다음이니 빈칸에는 🔶 가 와요.","되풀이되는 부분을 처음부터 묶어 보면 차례가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#2','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'mc','auto','그림에서 반복되는 부분은 어느 것인가요?',ARRAY['M1-2-u5-X02','M1-2-u5-X01']::text[],false,'{"seq":2,"concept":"M1-2-u5-C1","difficulty":1,"kind":"mc","stem":"그림에서 반복되는 부분은 어느 것인가요?","asset":{"type":"pattern_row","items":["🔶","🔺","🔶","🔺","🔶","🔺"]},"options":[{"t":"🔶 🔺","correct":true},{"t":"🔶 🔶 🔺","mis":"M1-2-u5-X02"},{"t":"🔺 🔶","mis":"M1-2-u5-X01"}],"explanation":["처음부터 보면 🔶 다음에 🔺 가 와요.","🔶, 🔺 두 개가 한 덩이로 되풀이돼요.","중간부터 묶으면 🔺, 🔶 처럼 차례가 뒤바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#3','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'sa','auto','풍선이 둥근 풍선, 긴 풍선 차례로 6개 있어요. 둥근 풍선은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u5-C1","difficulty":1,"kind":"sa","stem":"풍선이 둥근 풍선, 긴 풍선 차례로 6개 있어요. 둥근 풍선은 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🎈","🪅","🎈","🪅","🎈","🪅"]},"answer":["3"],"variant_rule":{"repeat":{"ask":"count","unit":[2,2],"pool":["🎈","🪅","🎀","🎁"]}},"explanation":["🎈, 🪅 가 되풀이돼요.","한 덩이에 🎈 가 1개, 덩이가 3개라 🎈 는 3개예요.","전체에서 세어야지 한 덩이 안의 수만 답하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#4','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',1,'ox','auto','필통의 꽃무늬에서 🌸, 🌺 가 반복됩니다.',ARRAY['M1-2-u5-X02']::text[],true,'{"seq":4,"concept":"M1-2-u5-C1","difficulty":1,"kind":"ox","stem":"필통의 꽃무늬에서 🌸, 🌺 가 반복됩니다.","asset":{"type":"pattern_row","items":["🌸","🌺","🌸","🌺","🌸","🌺"]},"answer":"O","reason_options":[{"t":"🌸 다음 🌺, 그다음 다시 🌸 니까","correct":true},{"t":"🌸, 🌸, 🌺 가 반복되니까","mis":"M1-2-u5-X02"}],"variant_rule":{"repeat":{"ask":"next","unit":[2,2],"pool":["🌸","🌺","🌼","🌷"]}},"explanation":["🌸 다음에 🌺, 그다음에 다시 🌸 가 와요.","🌸, 🌺 두 개가 한 덩이예요 — 맞아요.","한 덩이에 몇 개가 들어가는지 묶어서 세어 보세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#5','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'mc','auto','화살표가 ↑, ↑, ↓, ↓ 로 반복돼요. 빈칸에 올 화살표는 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],false,'{"seq":5,"concept":"M1-2-u5-C1","difficulty":2,"kind":"mc","stem":"화살표가 ↑, ↑, ↓, ↓ 로 반복돼요. 빈칸에 올 화살표는 무엇인가요?","asset":{"type":"pattern_row","items":["↑","↑","↓","↓","↑","↑","↓",null]},"options":[{"t":"↓","correct":true},{"t":"↑","mis":"M1-2-u5-X01"},{"t":"→","mis":"M1-2-u5-X03"}],"explanation":["↑, ↑, ↓, ↓ 네 개가 한 덩이예요.","↑, ↑, ↓ 다음이니 ↓ 가 와요.","방향이 반복되는 규칙이에요 — 다른 방향은 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#6','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'mc','auto','곰 얼굴이 바로, 거꾸로 반복돼요. 중간에 빠진 것은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],false,'{"seq":6,"concept":"M1-2-u5-C1","difficulty":2,"kind":"mc","stem":"곰 얼굴이 바로, 거꾸로 반복돼요. 중간에 빠진 것은 무엇인가요?","asset":{"type":"pattern_row","items":["🐻","🙃","🐻",null,"🐻","🙃"]},"options":[{"t":"🙃","correct":true},{"t":"🐻","mis":"M1-2-u5-X01"},{"t":"🐷","mis":"M1-2-u5-X03"}],"explanation":["🐻, 🙃 가 되풀이돼요.","🐻 다음 자리가 비었으니 🙃 가 와요.","앞뒤 그림을 보고 차례를 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#7','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'match','auto','배열과 규칙을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u5-C1","difficulty":2,"kind":"match","stem":"배열과 규칙을 선으로 이어 보세요.","pairs":[{"l":"🔶 🔺 🔶 🔺","r":"🔶, 🔺 가 반복돼요"},{"l":"🧴 🩹 🩹 🧴 🩹 🩹","r":"🧴, 🩹, 🩹 가 반복돼요"},{"l":"↑ ↑ ↓ ↓ ↑ ↑ ↓ ↓","r":"↑, ↑, ↓, ↓ 가 반복돼요"}],"explanation":["처음부터 되풀이되는 부분을 묶어요.","🔶, 🔺 는 두 개, 🧴, 🩹, 🩹 는 세 개가 한 덩이예요.","↑, ↑, ↓, ↓ 는 네 개가 한 덩이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#8','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'sa','auto','🍎, 🍎, 🍐 가 되풀이되는 규칙으로 9개를 놓았어요. 🍎 는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M1-2-u5-C1","difficulty":2,"kind":"sa","stem":"🍎, 🍎, 🍐 가 되풀이되는 규칙으로 9개를 놓았어요. 🍎 는 모두 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🍎","🍎","🍐","🍎","🍎","🍐","🍎","🍎","🍐"]},"answer":["6"],"variant_rule":{"repeat":{"ask":"count","unit":[3,3],"pool":["🍎","🍐","🍇","🍊"]}},"explanation":["한 덩이 🍎, 🍎, 🍐 에 🍎 가 2개 있어요.","9개면 덩이가 3개라 🍎 는 6개예요.","2는 한 덩이 안의 수 — 전체에서 세어야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_basic#9','math',1,2,'u5','L02','g1_2_math_u5_L02_basic','lesson_basic','M1-2-u5-C1',2,'mc','auto','그림의 규칙을 가장 똑똑히 말한 것은 어느 것인가요?',ARRAY['M1-2-u5-X03','M1-2-u5-X02']::text[],false,'{"seq":9,"concept":"M1-2-u5-C1","difficulty":2,"kind":"mc","stem":"그림의 규칙을 가장 똑똑히 말한 것은 어느 것인가요?","asset":{"type":"pattern_row","items":["🧴","🧴","✂️","🧴","🧴","✂️"]},"options":[{"t":"풀, 풀, 가위가 반복돼요","correct":true},{"t":"물건이 여러 개 있어요","mis":"M1-2-u5-X03"},{"t":"풀, 가위가 반복돼요","mis":"M1-2-u5-X02"}],"explanation":["🧴 🧴 ✂️ 다음에 다시 🧴 🧴 ✂️ 가 와요.","「풀, 풀, 가위」 세 개가 한 덩이예요.","무엇이 어떻게 반복되는지 똑똑히 말해야 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
