INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#3','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'mc','auto','곰 얼굴이 바로, 거꾸로 반복돼요. 빈칸 두 개에 순서대로 올 것은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X02']::text[],false,'{"seq":3,"concept":"M1-2-u5-C1","difficulty":3,"kind":"mc","stem":"곰 얼굴이 바로, 거꾸로 반복돼요. 빈칸 두 개에 순서대로 올 것은 무엇인가요?","asset":{"type":"pattern_row","items":["🐻","🙃","🐻","🙃","🐻","🙃",null,null]},"options":[{"t":"🐻, 🙃","correct":true},{"t":"🙃, 🐻","mis":"M1-2-u5-X01"},{"t":"🐻, 🐻","mis":"M1-2-u5-X02"}],"explanation":["🐻, 🙃 가 되풀이돼요.","🙃 다음은 🐻, 그다음은 🙃 예요.","빈칸이 둘이어도 차례대로 이어 가면 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#4','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'ox','auto','연결 모형이 🟩 🟩 🟦 🟩 🟩 🟦 로 놓여 있어요. 개수가 2개, 1개로 반복됩니다.',ARRAY['M1-2-u5-X01']::text[],false,'{"seq":4,"concept":"M1-2-u5-C1","difficulty":3,"kind":"ox","stem":"연결 모형이 🟩 🟩 🟦 🟩 🟩 🟦 로 놓여 있어요. 개수가 2개, 1개로 반복됩니다.","asset":{"type":"pattern_row","items":["🟩","🟩","🟦","🟩","🟩","🟦"]},"answer":"O","reason_options":[{"t":"🟩 2개 다음 🟦 1개가 되풀이되니까","correct":true},{"t":"개수가 1개, 1개, 2개로 반복되니까","mis":"M1-2-u5-X01"}],"explanation":["🟩 🟩 🟦 가 한 덩이예요.","초록 2개, 파랑 1개가 되풀이돼요 — 맞아요.","색으로 말하면 초록, 초록, 파랑이 반복돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L02_challenge#5','math',1,2,'u5','L02','g1_2_math_u5_L02_challenge','lesson_challenge','M1-2-u5-C1',3,'mc','auto','🔶 🔺 🔶 🔺 에서 반복되는 부분에 묶음 표시를 바르게 한 것은 어느 것인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X02']::text[],false,'{"seq":5,"concept":"M1-2-u5-C1","difficulty":3,"kind":"mc","stem":"🔶 🔺 🔶 🔺 에서 반복되는 부분에 묶음 표시를 바르게 한 것은 어느 것인가요?","options":[{"t":"(🔶 🔺) (🔶 🔺)","correct":true},{"t":"🔶 (🔺 🔶) 🔺","mis":"M1-2-u5-X01"},{"t":"(🔶 🔺 🔶) (🔺)","mis":"M1-2-u5-X02"}],"explanation":["처음 그림부터 묶어요.","🔶, 🔺 두 개씩 묶으면 같은 덩이가 되풀이돼요.","묶음의 크기가 다르면 되풀이가 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
