INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#1','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',2,'mc','auto','주사위 배열이에요. 빈칸에 올 것은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X10']::text[],true,'{"seq":1,"concept":"M1-2-u5-C6","difficulty":2,"kind":"mc","stem":"주사위 배열이에요. 빈칸에 올 것은 무엇인가요?","asset":{"type":"pattern_row","items":["🎲","🎯","🎯","🎲","🎯","🎯","🎲",null]},"options":[{"t":"🎯","correct":true},{"t":"🎲","mis":"M1-2-u5-X01"},{"t":"🃏","mis":"M1-2-u5-X10"}],"variant_rule":{"repeat":{"ask":"next","unit":[3,3],"pool":["🎲","🎯","🃏","🎴"]}},"explanation":["🎲, 🎯, 🎯 세 개가 한 덩이예요.","🎲 다음이니 🎯 예요.","눈의 수로 쓰면 2, 5, 5 가 되풀이돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
