INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#3','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',3,'ox','auto','🙆 🙋 🙋 (두 팔 벌리기, 한 팔 들기, 한 팔 들기) 는 2, 1, 1 로 나타낼 수 있습니다.',ARRAY['M1-2-u5-X10']::text[],false,'{"seq":3,"concept":"M1-2-u5-C6","difficulty":3,"kind":"ox","stem":"🙆 🙋 🙋 (두 팔 벌리기, 한 팔 들기, 한 팔 들기) 는 2, 1, 1 로 나타낼 수 있습니다.","answer":"O","reason_options":[{"t":"두 팔은 2, 한 팔은 1로 바꾸면 되풀이가 같으니까","correct":true},{"t":"몸짓은 수로 나타낼 수 없으니까","mis":"M1-2-u5-X10"}],"explanation":["두 팔은 2, 한 팔은 1로 정해요.","2, 1, 1 이 되풀이돼요 — 맞아요.","팔의 수로 나타내면 규칙이 또렷해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#4','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',3,'mc','auto','■ ★ ★ ■ ★ ★ 무늬를 몸으로 나타낸 것은 어느 것인가요?',ARRAY['M1-2-u5-X02','M1-2-u5-X01']::text[],false,'{"seq":4,"concept":"M1-2-u5-C6","difficulty":3,"kind":"mc","stem":"■ ★ ★ ■ ★ ★ 무늬를 몸으로 나타낸 것은 어느 것인가요?","options":[{"t":"🙆 🙋 🙋 🙆 🙋 🙋","correct":true},{"t":"🙆 🙋 🙆 🙋","mis":"M1-2-u5-X02"},{"t":"🙆 🙆 🙋 🙆 🙆 🙋","mis":"M1-2-u5-X01"}],"explanation":["■ ★ ★ 은 「하나, 둘」 덩이예요.","🙆 🙋 🙋 도 「하나, 둘」이라 같은 규칙이에요.","🙆 🙆 🙋 는 「둘, 하나」라 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#5','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',3,'sa','auto','2, 3, 2, 3 규칙을 △, ○ 으로 나타내어 8개를 놓았어요. △ 는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"M1-2-u5-C6","difficulty":3,"kind":"sa","stem":"2, 3, 2, 3 규칙을 △, ○ 으로 나타내어 8개를 놓았어요. △ 는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["2 를 △, 3 을 ○ 으로 바꿔요.","△ ○ 이 한 덩이, 8개면 덩이 4개라 △ 는 4개예요.","나타내는 방법이 바뀌어도 개수는 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
