INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#7','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',3,'match','auto','같은 규칙끼리 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"M1-2-u5-C6","difficulty":3,"kind":"match","stem":"같은 규칙끼리 선으로 이어 보세요.","pairs":[{"l":"△ ○ △ ○","r":"2, 3, 2, 3"},{"l":"🙆 🙋 🙋","r":"1, 2, 2"},{"l":"🎲 🎲 🎯","r":"5, 5, 8"}],"explanation":["「하나, 하나」·「하나, 둘」·「둘, 하나」 덩이를 견줘요.","겉모습이 달라도 덩이가 같으면 같은 규칙이에요.","수로 바꿔 보면 짝이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#8','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',4,'sa','auto','2, 5, 5 가 되풀이되는 규칙에서 12번째 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u5-C6","difficulty":4,"kind":"sa","stem":"2, 5, 5 가 되풀이되는 규칙에서 12번째 수는 무엇인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["2, 5, 5 세 개가 한 덩이예요.","12는 3, 6, 9, 12 — 덩이의 셋째 자리라 5예요.","몇 번째인지 세 개씩 묶어 세요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#9','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',4,'mc','auto','🚲 🛺 🚲 🛺 와 △ ○ △ ○ 은 겉모습이 다른데 같은 규칙이에요. 그 까닭은 무엇인가요?',ARRAY['M1-2-u5-X04','M1-2-u5-X02']::text[],false,'{"seq":9,"concept":"M1-2-u5-C6","difficulty":4,"kind":"mc","stem":"🚲 🛺 🚲 🛺 와 △ ○ △ ○ 은 겉모습이 다른데 같은 규칙이에요. 그 까닭은 무엇인가요?","options":[{"t":"되풀이되는 부분이 「하나, 하나」로 같아서","correct":true},{"t":"쓴 물건이 같아서","mis":"M1-2-u5-X04"},{"t":"개수가 여섯 개로 같아서","mis":"M1-2-u5-X02"}],"explanation":["🚲 🛺 도, △ ○ 도 두 개가 한 덩이예요.","덩이가 같으면 같은 규칙이에요.","물건이나 개수가 아니라 되풀이되는 부분을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_L07_challenge#10','math',1,2,'u5','L07','g1_2_math_u5_L07_challenge','lesson_challenge','M1-2-u5-C6',4,'essay','teacher','🚸 🚳 🚸 🚳 규칙을 모양·수·몸짓 세 가지로 나타내고, 세 가지가 같은 규칙인 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M1-2-u5-C6","difficulty":4,"kind":"essay","stem":"🚸 🚳 🚸 🚳 규칙을 모양·수·몸짓 세 가지로 나타내고, 세 가지가 같은 규칙인 까닭을 쓰세요.","answer_guide":"① 모양 △ ○ △ ○ ② 수 1, 2, 1, 2(다른 수도 가능) ③ 몸짓 🙆 🙋 🙆 🙋 ④ 「하나, 하나」 덩이가 같다는 까닭 — 넷 다 있으면 만점, 두 가지만 쓰면 절반","explanation":["모양으로는 △, ○ 으로 나타내요.","수로는 1, 2, 몸짓으로는 두 팔, 한 팔로 나타내요.","되풀이되는 부분이 같아서 같은 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#1','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C1',1,'mc','auto','🔶, 🔺 가 반복돼요. 빈칸에 올 것은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X03']::text[],true,'{"seq":1,"concept":"M1-2-u5-C1","difficulty":1,"kind":"mc","stem":"🔶, 🔺 가 반복돼요. 빈칸에 올 것은 무엇인가요?","asset":{"type":"pattern_row","items":["🔶","🔺","🔶","🔺","🔶","🔺",null]},"options":[{"t":"🔶","correct":true},{"t":"🔺","mis":"M1-2-u5-X01"},{"t":"🟦","mis":"M1-2-u5-X03"}],"variant_rule":{"repeat":{"ask":"next","unit":[2,2],"pool":["🔶","🔺","🟦","🍊"]}},"explanation":["🔶, 🔺 두 개가 한 덩이예요.","🔺 다음이니 🔶 가 와요.","되풀이되는 부분을 처음부터 묶어 보면 차례가 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#2','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C1',1,'mc','auto','그림에서 반복되는 부분은 어느 것인가요?',ARRAY['M1-2-u5-X02','M1-2-u5-X01']::text[],false,'{"seq":2,"concept":"M1-2-u5-C1","difficulty":1,"kind":"mc","stem":"그림에서 반복되는 부분은 어느 것인가요?","asset":{"type":"pattern_row","items":["🔶","🔺","🔶","🔺","🔶","🔺"]},"options":[{"t":"🔶 🔺","correct":true},{"t":"🔶 🔶 🔺","mis":"M1-2-u5-X02"},{"t":"🔺 🔶","mis":"M1-2-u5-X01"}],"explanation":["처음부터 보면 🔶 다음에 🔺 가 와요.","🔶, 🔺 두 개가 한 덩이로 되풀이돼요.","중간부터 묶으면 차례가 뒤바뀌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#3','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C1',1,'sa','auto','🎈, 🪅 가 반복되는 규칙으로 6개를 놓았어요. 🎈 는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M1-2-u5-C1","difficulty":1,"kind":"sa","stem":"🎈, 🪅 가 반복되는 규칙으로 6개를 놓았어요. 🎈 는 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🎈","🪅","🎈","🪅","🎈","🪅"]},"answer":["3"],"variant_rule":{"repeat":{"ask":"count","unit":[2,2],"pool":["🎈","🪅","🎀","🎁"]}},"explanation":["🎈, 🪅 가 한 덩이예요.","6개면 덩이가 3개라 🎈 는 3개예요.","전체에서 세어야지 한 덩이 안의 수만 답하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#4','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C1',2,'match','auto','배열과 규칙을 선으로 이어 보세요.','{}'::text[],false,'{"seq":4,"concept":"M1-2-u5-C1","difficulty":2,"kind":"match","stem":"배열과 규칙을 선으로 이어 보세요.","pairs":[{"l":"🔶 🔺 🔶 🔺","r":"🔶, 🔺 가 반복돼요"},{"l":"🧴 🩹 🩹 🧴 🩹 🩹","r":"🧴, 🩹, 🩹 가 반복돼요"},{"l":"↑ ↑ ↓ ↓","r":"↑, ↑, ↓, ↓ 가 반복돼요"}],"explanation":["처음부터 되풀이되는 부분을 묶어요.","두 개·세 개·네 개 덩이를 구별해요.","무엇이 어떻게 반복되는지 말로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#5','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C1',3,'error','auto','지우가 🟥 🟦 🟦 🟥 🟦 🟦 를 보고 이렇게 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#6','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C2',1,'ox','auto','노랑, 파랑, 파랑 과 빨강, 초록, 초록 은 같은 규칙입니다.',ARRAY['M1-2-u5-X04']::text[],false,'{"seq":6,"concept":"M1-2-u5-C2","difficulty":1,"kind":"ox","stem":"노랑, 파랑, 파랑 과 빨강, 초록, 초록 은 같은 규칙입니다.","answer":"O","reason_options":[{"t":"반복되는 부분의 차례가 같으니까","correct":true},{"t":"색이 다르니까 다른 규칙이니까","mis":"M1-2-u5-X04"}],"explanation":["둘 다 되풀이되는 부분의 길이와 차례가 같아요.","색은 달라도 같은 규칙이에요.","규칙은 어떻게 되풀이되느냐로 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#7','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C2',2,'mc','auto','물건을 놓았어요. 규칙이 있는 것은 어느 것인가요?',ARRAY['M1-2-u5-X05']::text[],false,'{"seq":7,"concept":"M1-2-u5-C2","difficulty":2,"kind":"mc","stem":"물건을 놓았어요. 규칙이 있는 것은 어느 것인가요?","options":[{"t":"🪨 🌰 🌰 🪨 🌰 🌰","correct":true},{"t":"🪨 🌰 🪨 🪨 🌰 🌰","mis":"M1-2-u5-X05"},{"t":"🌰 🪨 🪨 🌰 🪨 🌰","mis":"M1-2-u5-X05"}],"explanation":["🪨 🌰 🌰 가 두 번 되풀이돼요.","다른 둘은 같은 덩이가 되풀이되지 않아요.","되풀이되는 부분에 ○ 를 해 보면 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#8','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C2',2,'sa','auto','🟩, 🟦, 🟦 규칙으로 9개를 이었어요. 🟦 는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"M1-2-u5-C2","difficulty":2,"kind":"sa","stem":"🟩, 🟦, 🟦 규칙으로 9개를 이었어요. 🟦 는 몇 개인가요? 숫자로 쓰세요.","asset":{"type":"pattern_row","items":["🟩","🟦","🟦","🟩","🟦","🟦","🟩","🟦","🟦"]},"answer":["6"],"explanation":["한 덩이 🟩, 🟦, 🟦 에 🟦 가 2개 있어요.","9개면 덩이가 3개라 🟦 는 6개예요.","2는 한 덩이 안의 수예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#9','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C2',3,'error','auto','민수가 친구의 「검정, 검정, 흰색」 규칙을 보고 풀, 가위, 가위 를 놓고 「같은 규칙이야」라고 했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#10','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C3',1,'mc','auto','가방 무늬예요. 둘째 줄의 빈칸에 올 색은 무엇인가요?',ARRAY['M1-2-u5-X01','M1-2-u5-X05']::text[],false,'{"seq":10,"concept":"M1-2-u5-C3","difficulty":1,"kind":"mc","stem":"가방 무늬예요. 둘째 줄의 빈칸에 올 색은 무엇인가요?","asset":{"type":"pattern_grid","rows":[["🟨","🟦","🟨","🟦"],["🟦","🟨","🟦",null]]},"options":[{"t":"🟨","correct":true},{"t":"🟦","mis":"M1-2-u5-X01"},{"t":"🟥","mis":"M1-2-u5-X05"}],"explanation":["첫째 줄은 🟨, 🟦 가 반복돼요.","둘째 줄은 🟦, 🟨 가 반복되니 빈칸은 🟨 예요.","네 칸이 한 덩이가 되어 되풀이돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#11','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C3',2,'mc','auto','■, ★, ★ 규칙으로 꾸민 무늬는 어느 것인가요?',ARRAY['M1-2-u5-X05','M1-2-u5-X02']::text[],false,'{"seq":11,"concept":"M1-2-u5-C3","difficulty":2,"kind":"mc","stem":"■, ★, ★ 규칙으로 꾸민 무늬는 어느 것인가요?","options":[{"t":"■ ★ ★ ■ ★ ★","correct":true},{"t":"■ ★ ■ ★ ★ ■","mis":"M1-2-u5-X05"},{"t":"■ ■ ★ ■ ■ ★","mis":"M1-2-u5-X02"}],"explanation":["■ ★ ★ 가 두 번 되풀이돼요.","■ ★ ■ ★ ★ ■ 는 덩이가 흐트러졌어요.","■ ■ ★ 은 「둘, 하나」라 다른 규칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#12','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C3',3,'ox','auto','첫째 줄이 ■ ★ ■ ★, 둘째 줄이 ★ ■ ★ ■ 인 무늬는 규칙이 있는 무늬입니다.',ARRAY['M1-2-u5-X05']::text[],false,'{"seq":12,"concept":"M1-2-u5-C3","difficulty":3,"kind":"ox","stem":"첫째 줄이 ■ ★ ■ ★, 둘째 줄이 ★ ■ ★ ■ 인 무늬는 규칙이 있는 무늬입니다.","asset":{"type":"pattern_grid","rows":[["■","★","■","★"],["★","■","★","■"]]},"answer":"O","reason_options":[{"t":"두 줄이 한 덩이가 되어 되풀이되니까","correct":true},{"t":"줄마다 순서가 다르면 규칙이 아니니까","mis":"M1-2-u5-X05"}],"explanation":["첫째 줄 ■ ★, 둘째 줄 ★ ■ 가 한 덩이예요.","그 덩이가 되풀이되니 규칙 있는 무늬예요.","줄을 넘어서도 되풀이되는 부분을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#13','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C3',4,'essay','teacher','■ 와 ★ 두 모양으로 나만의 규칙을 만들어 여섯 칸 무늬를 쓰고, 규칙을 말로 쓰세요. 둘째 줄을 첫째 줄과 반대로 하면 어떻게 되는지도 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"M1-2-u5-C3","difficulty":4,"kind":"essay","stem":"■ 와 ★ 두 모양으로 나만의 규칙을 만들어 여섯 칸 무늬를 쓰고, 규칙을 말로 쓰세요. 둘째 줄을 첫째 줄과 반대로 하면 어떻게 되는지도 쓰세요.","answer_guide":"① 두 모양으로 6칸 무늬 ② 규칙 문장 ③ 둘째 줄 = 자리 바꿈 — 셋 다 있으면 만점, 무늬만 쓰면 절반","explanation":["두 모양으로 반복되는 부분을 만들어요.","그 부분을 되풀이해 여섯 칸을 채워요.","둘째 줄은 자리를 바꿔 놓아도 규칙 있는 무늬예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#14','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C4',1,'sa','auto','3, 7 가 되풀이되는 수 배열이에요. 빈칸에 알맞은 수를 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M1-2-u5-C4","difficulty":1,"kind":"sa","stem":"3, 7 가 되풀이되는 수 배열이에요. 빈칸에 알맞은 수를 쓰세요.","asset":{"type":"number_line","cells":[3,7,3,7,3,null]},"answer":["7"],"variant_rule":{"numrule":{"kind":"repeat"}},"explanation":["3, 7 가 한 덩이예요.","3 다음이니 7이에요.","수도 되풀이될 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#15','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C4',2,'mc','auto','28부터 시작하여 2씩 작아지는 수 배열이에요. 빈칸에 올 수는 무엇인가요?',ARRAY['M1-2-u5-X07','M1-2-u5-X06']::text[],true,'{"seq":15,"concept":"M1-2-u5-C4","difficulty":2,"kind":"mc","stem":"28부터 시작하여 2씩 작아지는 수 배열이에요. 빈칸에 올 수는 무엇인가요?","asset":{"type":"number_line","cells":[28,26,24,null,20]},"options":[{"t":"22","correct":true},{"t":"26","mis":"M1-2-u5-X07"},{"t":"23","mis":"M1-2-u5-X06"}],"variant_rule":{"numrule":{"kind":"skip","step":[2,2],"dir":"down"}},"explanation":["28, 26, 24 — 2씩 작아져요.","24보다 2 작은 22예요.","옆의 수와 차이를 재고 방향을 지켜요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_math_u5_review_a#16','math',1,2,'u5','review','g1_2_math_u5_review_a','unit_review','M1-2-u5-C4',2,'match','auto','수 배열과 규칙을 선으로 이어 보세요.','{}'::text[],false,'{"seq":16,"concept":"M1-2-u5-C4","difficulty":2,"kind":"match","stem":"수 배열과 규칙을 선으로 이어 보세요.","pairs":[{"l":"10, 11, 12, 13","r":"10부터 1씩 커져요"},{"l":"2, 4, 6, 8","r":"2부터 2씩 커져요"},{"l":"20, 18, 16, 14","r":"20부터 2씩 작아져요"}],"explanation":["커지는지, 작아지는지, 되풀이되는지 먼저 봐요.","옆의 수와 차이를 재요.","「몇부터 시작하여 몇씩」이라고 말해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
